    data = {
        "title": title,
        "triggers": [{"type": trigger, "value": value}],
        "actions": [{"type": action, "value": action_value or ""}],
        "priority": priority,
    }

    if rule_group_id:
        data["rule_group_id"] = rule_group_id
    if notes:
        data["notes"] = notes

    result = backend.create_rule(data)
    output(result)


